function unmappedTable(rows){return rows.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Código</th><th>Item fiscal</th><th>Qtd</th><th>Venda</th><th>Mapear para</th></tr></thead><tbody>${rows.slice(0,100).map(r=>`<tr><td>${esc(r.code||'')}</td><td>${esc(r.name||'')}</td><td>${n(r.qty)}</td><td>${brl(r.value)}</td><td><div class="actions"><select class="map-menu" data-code="${esc(r.code||'')}">${menuOptions()}</select><button class="small-btn map-save" data-code="${esc(r.code||'')}" data-name="${esc(r.name||'')}">Salvar</button></div></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty ok">Todos os itens importados estão mapeados ou não exigem ficha.</div>'}
function renderAnalytics(){const d=analysisDefaultDate();return `${header('Conciliação de Proteínas & XML','Fluxo simplificado: importe o ZIP, escolha o período e compare estoque físico, produção de proteínas, perdas, consumo teórico e CMV.',`<button id="analytics-refresh" class="btn soft">Atualizar dados</button>`)}${isAdmin()?adminXmlImportPanelHtml():''}<section class="panel" style="margin-top:16px"><div class="panel-head"><div><h2>2. Escolher data ou período</h2><small class="muted">De = Até analisa um dia. Datas diferentes acumulam todas as movimentações e vendas no intervalo.</small></div><span class="badge ok">Padrão: ontem</span></div><div class="panel-body"><div class="filters analytics-filters"><label>De<input id="an-from" type="date" value="${d}"></label><label>Até<input id="an-to" type="date" value="${d}"></label><button id="an-yesterday" class="btn soft" type="button">Ontem (${fmtDate(d)})</button><button id="an-last7" class="btn soft" type="button">Últimos 7 dias</button><button id="an-month" class="btn soft" type="button">Mês até a data final</button><button id="an-latest-xml" class="btn soft" type="button">Última data do XML</button></div><div class="flow-note" style="margin-top:12px"><b>3. Analisar:</b> a tela cruza a última posição física anterior, entradas, transferências, beneficiamentos, perdas, produção de proteínas, sobra física final e consumo teórico das vendas XML.</div></div></section><div id="analytics-live">${analyticsLiveHtml()}</div>`}
function adminXmlImportPanelHtml(){const imports=cache.salesImports||[];return `<section class="panel xml-import-panel"><div class="panel-head"><div><h2>1. Importar XML / NFC-e</h2><small class="muted">Primeiro importe o ZIP. Depois escolha a data ou o período que deseja analisar.</small></div><span class="badge ok">ADMIN</span></div><div class="panel-body"><div class="actions"><button id="xml-choose-btn" class="btn primary" type="button">Escolher arquivo ZIP</button><button id="xml-import-btn" class="btn accent" type="button">Importar XML</button><button id="xml-validate-btn" class="btn soft" type="button">Validar ZIP</button><button id="xml-health-btn" class="btn soft" type="button">Testar conexão XML</button></div><div id="xml-selected-file" class="warning" style="margin-top:10px">${selectedXmlFile?`✓ Selecionado: ${esc(selectedXmlFile.name)} · ${(selectedXmlFile.size/1024/1024).toFixed(1)} MB`:'Nenhum arquivo ZIP selecionado.'}</div><div id="xml-status" class="warning" style="margin-top:10px" hidden></div><p class="muted"><b>Importador 3.12:</b> o seletor do arquivo fica fora da área que é atualizada em tempo real, evitando perder o ZIP no celular ou computador. O ZIP pode conter XMLs em subpastas. A gravação é feita em lotes por RPC no Supabase e não depende da tela permanecer parada.</p>${imports.length?`<div class="section-title">Importações existentes</div><div class="status-list" style="max-height:300px;overflow:auto">${imports.slice(0,40).map(i=>`<div class="status-line"><span><b>${esc(i.filename)}</b><small class="muted" style="display:block">${fmtDate(i.period_start)} a ${fmtDate(i.period_end)} · ${esc(i.status||'IMPORTED')}</small></span><span class="actions"><b>${brl(i.net_sales)}</b><button class="small-btn danger-lite xml-delete" type="button" data-id="${i.id}">Apagar</button></span></div>`).join('')}</div><div style="margin-top:10px"><button id="xml-delete-all" class="btn danger" type="button">Apagar TODOS os XMLs importados</button></div>`:''}</div></section>`}
function adminAnalyticsHtml(day){const ms=monthStart(day),unmapped=unmappedSummary();return `<div class="section-title">Administração da análise</div><div class="two-col"><section class="panel"><div class="panel-head"><h2>Estoque inicial de proteínas</h2></div><div class="panel-body"><form id="opening-form" class="form-grid"><label>Mês<input name="month_start" type="month" value="${ms.slice(0,7)}" required></label><label>Proteína<select name="protein_id">${proteinOptions()}</select></label><label>Estágio<select name="stage"><option value="WHOLE">Inteiro</option><option value="TRIMMED">Pré-limpo</option><option value="CLEAN">Limpo</option><option value="PREPARED">Preparado</option></select></label><label>Local<select name="location">${locationOptions('CENTRAL',true,true,true)}</select></label><label>Quantidade kg<input name="qty_kg" inputmode="decimal" value="0" required></label><label>Custo/kg (opcional)<input name="cost_kg" inputmode="decimal"></label><label class="full">Observação<input name="notes"></label><div class="form-actions full"><button class="btn accent" type="submit">Salvar estoque inicial</button></div></form></div></section><section class="panel"><div class="panel-head"><h2>Início do ciclo V3 por setores</h2></div><div class="panel-body"><label>Data de corte<input id="sector-cutover-input" type="date" value="${sectorCutoverDate()}"></label><div class="actions" style="margin-top:10px"><button id="sector-cutover-save" class="btn soft" type="button">Salvar data de corte</button></div><p class="muted">Vendas anteriores permanecem na lógica histórica. A partir desta data, o XML baixa Sushi Bar, Poke ou Cozinha conforme a ficha.</p></div></section></div><section class="panel"><div class="panel-head"><h2>Pendências XML → Produto</h2><span class="badge ${unmapped.length?'warn':'ok'}">${unmapped.length} códigos</span></div><div class="panel-body">${unmappedTable(unmapped)}</div></section>`}
function analyticsLiveHtml(){const {from,to}=analysisRange(),stock=theoreticalProteinStock(to),stockGroups={WHOLE:0,TRIMMED:0,CLEAN:0,PORTIONED:0,PREPARED:0};stock.forEach(r=>stockGroups[r.stage]=(stockGroups[r.stage]||0)+n(r.qty));return `${analysisReadinessHtml(from,to)}${rangeSummaryHtml(from,to)}${rangeReconciliationHtml(from,to)}${periodMovementHtml(from,to)}${rangeProteinHtml(from,to)}${rangeSectorHtml(from,to)}${rangeYieldHtml(from,to)}${rangeItemHtml(from,to)}<section class="panel"><div class="panel-head"><h2>Posição de estoque no final do período</h2><div class="actions"><span class="badge">Inteiro ${kg(stockGroups.WHOLE||0)}</span><span class="badge">Pré-limpo ${kg(stockGroups.TRIMMED||0)}</span><span class="badge">Limpo ${kg(stockGroups.CLEAN||0)}</span><span class="badge">Porcionado ${kg(stockGroups.PORTIONED||0)}</span><span class="badge">Preparado ${kg(stockGroups.PREPARED||0)}</span></div></div><div class="panel-body">${theoreticalStockTable(stock,to)}</div></section>${isAdmin()?adminAnalyticsHtml(to):''}`}

async function parseFiscalZip(file,onProgress=()=>{}){
 if(!window.JSZip)throw new Error('Biblioteca ZIP não carregou. Atualize a página e tente novamente.');
 if(!file)throw new Error('Selecione o arquivo ZIP.');
 if(!/\.zip$/i.test(file.name||''))throw new Error('O arquivo precisa estar no formato .ZIP.');
 const zip=await JSZip.loadAsync(file),canceled=new Set(),docs=[],errors=[];
 const entries=Object.values(zip.files).filter(x=>!x.dir&&/\.xml$/i.test(x.name));
 if(!entries.length)throw new Error('O ZIP não contém arquivos XML.');
 let processed=0;
 for(const e of entries){
  try{
   const txt=await e.async('text'),xml=parseXmlText(txt,e.name),tp=xml.getElementsByTagNameNS('*','tpEvento')[0]?.textContent?.trim(),eventKey=xml.getElementsByTagNameNS('*','chNFe')[0]?.textContent?.trim(),inf=xml.getElementsByTagNameNS('*','infNFe')[0];
   if(tp==='110111'||(!inf&&eventKey&&xml.getElementsByTagNameNS('*','infEvento').length)){canceled.add(eventKey);processed++;continue}
   if(!inf){processed++;continue}
   const key=String(inf.getAttribute('Id')||'').replace(/^NFe/,''),ide=xml.getElementsByTagNameNS('*','ide')[0],date=(ide?.getElementsByTagNameNS('*','dhEmi')[0]?.textContent||ide?.getElementsByTagNameNS('*','dEmi')[0]?.textContent||'').slice(0,10),number=ide?.getElementsByTagNameNS('*','nNF')[0]?.textContent||'';
   if(!key||!/^[0-9]{40,50}$/.test(key))throw new Error('Chave da NF-e não encontrada.');
   if(!/^\d{4}-\d{2}-\d{2}$/.test(date))throw new Error('Data de emissão não encontrada.');
   let line=0;
   for(const det of [...xml.getElementsByTagNameNS('*','det')]){line++;const prod=det.getElementsByTagNameNS('*','prod')[0];if(!prod)continue;const get=t=>prod.getElementsByTagNameNS('*',t)[0]?.textContent?.trim()||'',code=get('cProd'),name=get('xProd')||'ITEM SEM DESCRIÇÃO',qty=n(get('qCom')),unit=n(get('vUnCom')),gross=n(get('vProd')),disc=n(get('vDesc')),net=Math.max(0,gross-disc);docs.push({document_key:key,document_number:number,event_date:date,line_no:line,item_code:code,item_name:name,qty,unit_price:unit,gross_value:gross,discount_value:disc,net_value:net,cancelled:false,raw_source:e.name})}
  }catch(err){errors.push(`${e.name}: ${errText(err)}`)}
  processed++;if(processed%40===0||processed===entries.length)onProgress(`Lendo XMLs… ${processed}/${entries.length}`)
 }
 docs.forEach(r=>{if(canceled.has(r.document_key))r.cancelled=true});
 const dedup=new Map();for(const r of docs)dedup.set(`${r.document_key}|${r.line_no}`,r);const lines=[...dedup.values()];
 if(!lines.length)throw new Error(`Nenhuma linha de venda válida foi encontrada. ${errors[0]||''}`.trim());
 return {lines,canceled,files:entries.length,errors,duplicates:docs.length-lines.length}
}
function resolveMenuForFiscal(code,name){const mp=cache.fiscalMappings.find(m=>String(m.fiscal_code)===String(code)&&m.active!==false);if(mp)return {id:mp.menu_item_id,by:'MANUAL'};const exact=cache.menuItems.find(i=>String(i.code||'').trim()===String(code||'').trim());if(exact)return {id:exact.id,by:'CODE'};const norm=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toUpperCase().replace(/[^A-Z0-9]+/g,' ').trim();const same=cache.menuItems.find(i=>norm(i.name)===norm(name));return same?{id:same.id,by:'NAME'}:{id:null,by:'UNMAPPED'}}
function xmlFailureMessage(e){const m=errText(e);if(/pf_.*v311|PGRST202|Could not find the function|schema cache|relation .*sales_|does not exist/i.test(m))return `Estrutura XML incompleta no Supabase: ${m}. Execute supabase/21_ATUALIZACAO_COMPLETA_V312.sql e depois recarregue.`;if(/42501|permission|row-level security|violates row-level security/i.test(m))return `Permissão do banco recusou a importação: ${m}. Execute supabase/21_ATUALIZACAO_COMPLETA_V312.sql.`;return m}
function stableXmlInput(){let input=document.getElementById('pf-stable-xml-input');if(input)return input;input=document.createElement('input');input.id='pf-stable-xml-input';input.type='file';input.accept='.zip,application/zip,application/x-zip-compressed,application/octet-stream';input.style.position='fixed';input.style.left='-9999px';input.style.width='1px';input.style.height='1px';input.style.opacity='0';document.body.appendChild(input);input.addEventListener('change',()=>{xmlPickerOpen=false;const f=input.files?.[0]||null;if(f){selectedXmlFile=f;xmlStatus(`Arquivo selecionado: ${f.name}. Agora clique em Validar ZIP ou Importar XML.`,true)}updateXmlSelectedUi()});input.addEventListener('cancel',()=>{xmlPickerOpen=false;updateXmlSelectedUi()});return input}
function openStableXmlPicker(){if(xmlOperationBusy)return toast('Aguarde a operação XML atual.');const input=stableXmlInput();input.value='';xmlPickerOpen=true;input.click();setTimeout(()=>{if(xmlPickerOpen){xmlPickerOpen=false;updateXmlSelectedUi()}},120000)}
function selectedXml(){return selectedXmlFile||stableXmlInput().files?.[0]||null}
function updateXmlSelectedUi(){const el=$('#xml-selected-file'),file=selectedXml();if(!el)return;el.className=file?'warning ok-panel':'warning';el.textContent=file?`✓ Selecionado: ${file.name} · ${(file.size/1024/1024).toFixed(1)} MB`:'Nenhum arquivo ZIP selecionado.'}
function xmlStatus(message,ok=false){const status=$('#xml-status');if(!status)return;status.hidden=false;status.className=ok?'warning ok-panel':'warning';status.textContent=message}
function setXmlBusy(busy,label='Processando…'){xmlOperationBusy=!!busy;['#xml-choose-btn','#xml-validate-btn','#xml-import-btn','#xml-health-btn'].forEach(sel=>{const b=$(sel);if(b)b.disabled=!!busy});const i=$('#xml-import-btn');if(i)i.textContent=busy?label:'Importar XML';const v=$('#xml-validate-btn');if(v)v.textContent=busy?'Aguarde…':'Validar ZIP'}

async function xmlBackendMode(){
 try{const {data,error}=await sb.rpc('pf_xml_health_v311');if(!error){const out=Array.isArray(data)?data[0]:data;if(out?.ready!==false)return {mode:'v311',health:out}}}catch(_){}
 return {mode:'direct',health:null}
}
async function testXmlImportHealth(){
 if(!isAdmin())return toast('Somente ADMIN/SUPER_ADMIN pode testar a importação.');
 xmlStatus('Testando estrutura e permissões do XML…');
 try{
  const checks=await Promise.all([sb.from('sales_imports').select('id').limit(1),sb.from('sales_lines').select('id').limit(1),sb.from('fiscal_item_mappings').select('id').limit(1)]);
  const bad=checks.find(x=>x.error);if(bad)throw bad.error;
  const mode=await xmlBackendMode();
  xmlStatus(mode.mode==='v311'?'CONEXÃO XML OK ✓ Importador XML por RPC disponível.':'Tabelas XML acessíveis. O sistema usará modo direto de contingência; para máxima segurança execute o SQL 19.',true)
 }catch(e){xmlStatus(`TESTE XML FALHOU: ${xmlFailureMessage(e)}`)}
}
async function directCreateXmlImport(file,dates,docCount,lineCount,cancelCount,net){
 const row={org_id:membership.org_id,unit_id:membership.default_unit_id,filename:file.name,period_start:dates[0]||null,period_end:dates.length?dates[dates.length-1]:null,documents_count:docCount,lines_count:lineCount,cancelled_count:cancelCount,net_sales:net,status:'PROCESSING',imported_by:session.user.id,imported_at:now()};
 const {data,error}=await sb.from('sales_imports').insert(row).select('id').single();if(error)throw error;return data.id
}
async function directImportXmlRows(importId,rows,onProgress=()=>{}){
 const BATCH=80;let done=0,inserted=0,existing=0;
 for(let i=0;i<rows.length;i+=BATCH){
  const chunk=rows.slice(i,i+BATCH),keys=[...new Set(chunk.map(r=>r.document_key))];
  const {data:old,error:oldErr}=await sb.from('sales_lines').select('document_key,line_no').eq('unit_id',membership.default_unit_id).in('document_key',keys);if(oldErr)throw oldErr;
  const oldSet=new Set((old||[]).map(r=>`${r.document_key}|${r.line_no}`)),fresh=chunk.filter(r=>!oldSet.has(`${r.document_key}|${r.line_no}`));
  if(fresh.length){
   const dbRows=fresh.map(r=>({org_id:membership.org_id,unit_id:membership.default_unit_id,import_id:importId,event_date:r.event_date,document_key:r.document_key,document_number:r.document_number||null,line_no:r.line_no,item_code:r.item_code||null,item_name:r.item_name||'ITEM SEM DESCRIÇÃO',qty:n(r.qty),unit_price:n(r.unit_price),gross_value:n(r.gross_value),discount_value:n(r.discount_value),net_value:n(r.net_value),cancelled:!!r.cancelled,menu_item_id:r.menu_item_id||null,matched_by:r.matched_by||null,raw_source:r.raw_source||null,created_by:session.user.id}));
   const {error}=await sb.from('sales_lines').insert(dbRows);if(error)throw error;inserted+=fresh.length
  }
  existing+=chunk.length-fresh.length;
  try{const {data:oldLinks,error:ole}=await sb.from('sales_import_links').select('document_key,line_no').eq('import_id',importId).in('document_key',keys);if(ole)throw ole;const linkSet=new Set((oldLinks||[]).map(r=>`${r.document_key}|${r.line_no}`)),links=chunk.filter(r=>!linkSet.has(`${r.document_key}|${r.line_no}`)).map(r=>({org_id:membership.org_id,unit_id:membership.default_unit_id,import_id:importId,document_key:r.document_key,line_no:r.line_no}));if(links.length){const {error:le}=await sb.from('sales_import_links').insert(links);if(le)throw le}}catch(e){if(!/does not exist|schema cache|relation/i.test(errText(e)))throw e}
  done=Math.min(i+BATCH,rows.length);onProgress(done,rows.length)
 }
 const {error:u}=await sb.from('sales_imports').update({status:'IMPORTED'}).eq('id',importId);if(u)throw u;return {inserted,existing}
}

async function validateXmlZip(){
 const file=selectedXml();if(!file)return toast('Selecione o ZIP fiscal.');
 setXmlBusy(true,'Validando…');xmlStatus('Validando arquivo localmente…');
 try{
  if(!window.JSZip)throw new Error('Biblioteca ZIP (JSZip) não carregou.');
  const parsed=await parseFiscalZip(file,msg=>xmlStatus(msg));
  const valid=parsed.lines.filter(l=>!l.cancelled),business=valid.filter(l=>!(/^GORJETA$/i.test(String(l.item_name||'').trim())||String(l.item_code||'')==='99999'));
  const dates=valid.map(l=>l.event_date).filter(Boolean).sort(),net=business.reduce((s,l)=>s+n(l.net_value),0),grossNet=valid.reduce((s,l)=>s+n(l.net_value),0),docCount=new Set(valid.map(l=>l.document_key)).size,cancelCount=new Set(parsed.lines.filter(l=>l.cancelled).map(l=>l.document_key)).size;
  xmlStatus(`ZIP VÁLIDO ✓ ${parsed.files} XML(s) no arquivo. ${docCount} documento(s) fiscal(is) válido(s), ${valid.length} linha(s) fiscal(is), ${business.length} linha(s) consideradas no CMV. Cancelamentos: ${cancelCount}. Período: ${dates[0]||'—'} a ${dates.length?dates[dates.length-1]:'—'}. Venda fiscal líquida: ${brl(grossNet)}. Venda analisável sem gorjeta: ${brl(net)}.${parsed.errors.length?` Aviso: ${parsed.errors.length} XML(s) ignorados por erro de leitura.`:''}`,true)
 }catch(e){console.error('XML validation error',e);xmlStatus(`FALHA NA VALIDAÇÃO: ${xmlFailureMessage(e)}`)}
 finally{setXmlBusy(false)}
}
async function importXmlZip(){
 const file=selectedXml();if(!file)return toast('Selecione o ZIP fiscal.');
 if(!isAdmin())return toast('Somente ADMIN/SUPER_ADMIN pode importar vendas XML.');
 if(!session?.user?.id||!membership?.org_id||!membership?.default_unit_id)return toast('Sessão administrativa incompleta. Saia e entre novamente.');
 let importId=null,backend='direct';setXmlBusy(true,'Importando…');xmlStatus('1/6 Lendo e validando o ZIP…');
 try{
  if(!window.JSZip)throw new Error('Biblioteca ZIP (JSZip) não carregou.');
  const parsed=await parseFiscalZip(file,msg=>xmlStatus(`1/6 ${msg}`)),valid=parsed.lines.filter(l=>!l.cancelled),business=valid.filter(l=>!(/^GORJETA$/i.test(String(l.item_name||'').trim())||String(l.item_code||'')==='99999')),dates=valid.map(l=>l.event_date).filter(Boolean).sort(),net=business.reduce((z,l)=>z+n(l.net_value),0),docCount=new Set(valid.map(l=>l.document_key)).size,cancelCount=new Set(parsed.lines.filter(l=>l.cancelled).map(l=>l.document_key)).size;
  if(!docCount)throw new Error('Nenhum documento fiscal válido encontrado no ZIP.');
  const rows=parsed.lines.map(l=>{const m=resolveMenuForFiscal(l.item_code,l.item_name);return {...l,menu_item_id:m.id,matched_by:m.by}});
  const mode=await xmlBackendMode();backend=mode.mode;xmlStatus(`2/6 Banco pronto. Modo de importação: ${backend==='v311'?'RPC XML':'contingência direta'}. Criando lote…`);
  let inserted=0,existing=0;
  if(backend==='v311'){
   const {data:createData,error:createError}=await sb.rpc('pf_create_sales_import_v311',{p_filename:file.name,p_period_start:dates[0]||null,p_period_end:dates.length?dates[dates.length-1]:null,p_documents_count:docCount,p_lines_count:business.length,p_cancelled_count:cancelCount,p_net_sales:net});if(createError)throw createError;importId=Array.isArray(createData)?createData[0]:createData;if(typeof importId==='object'&&importId?.id)importId=importId.id;if(!importId)throw new Error('O Supabase não retornou o ID da importação.');
   const BATCH=80;for(let i=0;i<rows.length;i+=BATCH){const chunk=rows.slice(i,i+BATCH),{data,error}=await sb.rpc('pf_import_sales_lines_v311',{p_import_id:importId,p_rows:chunk});if(error)throw error;const out=Array.isArray(data)?data[0]:data;inserted+=n(out?.inserted);existing+=n(out?.existing);const done=Math.min(i+BATCH,rows.length);xmlStatus(`3/6 Gravando XML… ${done}/${rows.length} (${Math.round(done/rows.length*100)}%)`)}
   xmlStatus('4/6 Finalizando lote…');const {error:finishError}=await sb.rpc('pf_finish_sales_import_v311',{p_import_id:importId});if(finishError)throw finishError;
  }else{
   importId=await directCreateXmlImport(file,dates,docCount,business.length,cancelCount,net);
   const out=await directImportXmlRows(importId,rows,(done,total)=>xmlStatus(`3/6 Gravando em contingência… ${done}/${total} (${Math.round(done/total*100)}%)`));inserted=n(out.inserted);existing=n(out.existing)
  }
  xmlStatus('5/6 Recarregando vendas e recalculando estoque, perdas e CMV…');await loadAll(true);
  const latest=dates.length?dates[dates.length-1]:null,from=$('#an-from'),to=$('#an-to');if(latest){if(from)from.value=latest;if(to)to.value=latest}
  const live=$('#analytics-live');if(live)live.innerHTML=analyticsLiveHtml();bindAnalyticsActions();updateXmlSelectedUi();setCloud('Nuvem sincronizada','online');
  xmlStatus(`6/6 IMPORTAÇÃO CONCLUÍDA ✓ ${docCount} documento(s), ${business.length} linha(s) analisáveis, ${cancelCount} cancelamento(s). Venda analisável: ${brl(net)}. Período fiscal: ${dates[0]||'—'} a ${latest||'—'}. A análise foi posicionada na última data importada; você pode escolher qualquer data ou período.`,true);toast('XML importado com sucesso.')
 }catch(e){console.error('XML import error',e);if(importId&&sb){try{if(backend==='v311')await sb.rpc('pf_fail_sales_import_v311',{p_import_id:importId});else await sb.from('sales_imports').update({status:'FAILED'}).eq('id',importId)}catch(_){}}xmlStatus(`FALHA NA IMPORTAÇÃO: ${xmlFailureMessage(e)}`)}finally{setXmlBusy(false)}
}
async function deleteXmlImport(id){
 if(!isAdmin())return toast('Somente ADMIN/SUPER_ADMIN pode apagar XML importado.');
 if(xmlOperationBusy)return toast('Aguarde a operação XML atual terminar.');
 const imp=cache.salesImports.find(x=>x.id===id);if(!imp)return toast('Importação não localizada.');
 const reason=prompt(`Motivo para apagar o conteúdo desta importação?\n\n${imp.filename}\n${fmtDate(imp.period_start)} a ${fmtDate(imp.period_end)}\n${brl(imp.net_sales)}`,'Importação não deve mais ser considerada');
 if(reason===null)return;if(reason.trim().length<3)return toast('Informe um motivo com pelo menos 3 caracteres.');
 if(!confirm(`APAGAR O CONTEÚDO IMPORTADO de ${imp.filename}?\n\nOs dados exclusivos deste ZIP serão retirados das vendas XML, CMV e estoque teórico. Se uma mesma nota também pertence a outro ZIP ainda existente, ela continuará válida por aquele outro lote.\n\nEsta ação não apaga lançamentos operacionais.`))return;
 xmlOperationBusy=true;
 try{
  setCloud('Apagando importação XML…');
  let data,error;
  ({data,error}=await sb.rpc('pf_delete_sales_import',{p_import_id:id,p_reason:reason.trim()}));
  if(error&&/Could not find the function|schema cache|PGRST202|42883/i.test(errText(error))){({data,error}=await sb.rpc('pf_discard_sales_import',{p_import_id:id,p_reason:reason.trim()}))}
  if(error)throw error;
  const out=Array.isArray(data)?data[0]:data;
  toast(`Importação apagada. ${n(out?.removed_lines||0)} linha(s) exclusiva(s) removida(s).`);
  await loadAll(true);const el=$('#analytics-live');if(el)el.innerHTML=analyticsLiveHtml();bindAnalyticsActions();setCloud('Nuvem sincronizada','online')
 }catch(e){console.error(e);const msg=errText(e);toast(`Não foi possível apagar a importação: ${msg}`);if(/pf_delete_sales_import|pf_discard_sales_import|schema cache|does not exist/i.test(msg))xmlStatus('Execute uma única vez supabase/19_FECHAMENTO_ANALISE_XML_V311.sql no Supabase e recarregue o aplicativo.')}
 finally{xmlOperationBusy=false}
}
async function deleteAllXmlImports(){
 if(!isAdmin())return toast('Somente ADMIN/SUPER_ADMIN pode apagar XML importado.');
 if(xmlOperationBusy)return toast('Aguarde a operação XML atual terminar.');
 if(!cache.salesImports.length)return toast('Não há importações XML para apagar.');
 const total=cache.salesImports.reduce((s,i)=>s+n(i.net_sales),0);
 const token=prompt(`ATENÇÃO: isto apagará TODAS as importações XML desta unidade e retirará essas vendas dos cálculos de CMV/estoque.\n\nImportações: ${cache.salesImports.length}\nValor registrado: ${brl(total)}\n\nPara confirmar, digite: APAGAR XML`,'');
 if(token===null)return;if(String(token).trim().toUpperCase()!=='APAGAR XML')return toast('Confirmação incorreta. Nada foi apagado.');
 const reason=prompt('Informe o motivo para apagar todas as importações XML:','Reiniciar base de vendas XML');
 if(reason===null)return;if(reason.trim().length<3)return toast('Informe um motivo com pelo menos 3 caracteres.');
 xmlOperationBusy=true;
 try{
  setCloud('Apagando todos os XMLs…');
  const {data,error}=await sb.rpc('pf_delete_all_sales_imports',{p_reason:reason.trim()});if(error)throw error;
  const out=Array.isArray(data)?data[0]:data;
  toast(`XMLs apagados. ${n(out?.removed_lines||0)} linha(s) de venda removida(s).`);
  selectedXmlFile=null;await loadAll(true);const el=$('#analytics-live');if(el)el.innerHTML=analyticsLiveHtml();bindAnalyticsActions();setCloud('Nuvem sincronizada','online')
 }catch(e){console.error(e);const msg=errText(e);toast(`Não foi possível apagar todos os XMLs: ${msg}`);if(/pf_delete_all_sales_imports|schema cache|does not exist/i.test(msg))xmlStatus('Execute uma única vez supabase/19_FECHAMENTO_ANALISE_XML_V311.sql no Supabase e recarregue o aplicativo.')}
 finally{xmlOperationBusy=false}
}
async function saveOpeningStock(f){const d=fd(f),month=`${String(d.month_start).slice(0,7)}-01`,proteinId=d.protein_id||null,stage=d.stage||'CLEAN',location=d.location||'CENTRAL';if(!proteinId)throw new Error('Selecione a proteína.');const stockKey=`${proteinId}:none:${stage}:${location}`;const row={org_id:membership.org_id,unit_id:membership.default_unit_id,month_start:month,stock_key:stockKey,protein_id:proteinId,menu_item_id:null,stage,location,qty_kg:n(d.qty_kg),qty_units:0,cost_kg:d.cost_kg?n(d.cost_kg):null,notes:d.notes||null,created_by:session.user.id};const {error}=await sb.from('monthly_opening_stock').upsert(row,{onConflict:'unit_id,month_start,stock_key'});if(error)throw error;toast('Estoque inicial de proteína salvo.');await refreshAndPatch()}
async function saveFiscalMapping(code,name,menuId){if(!menuId)return toast('Selecione um produto.');const row={org_id:membership.org_id,fiscal_code:code,fiscal_name:name,menu_item_id:menuId,active:true,created_by:session.user.id};const {error}=await sb.from('fiscal_item_mappings').upsert(row,{onConflict:'org_id,fiscal_code'});if(error)return toast(error.message);const {error:u}=await sb.from('sales_lines').update({menu_item_id:menuId,matched_by:'MANUAL'}).eq('org_id',membership.org_id).eq('item_code',code);if(u)return toast(u.message);toast('Mapeamento aplicado aos XMLs já importados.');await refreshAndPatch()}
function rerenderAnalytics(){const el=$('#analytics-live');if(el)el.innerHTML=analyticsLiveHtml();bindAnalyticsActions()}
function bindAnalyticsActions(){
 const from=$('#an-from'),to=$('#an-to');if(from)from.onchange=rerenderAnalytics;if(to)to.onchange=rerenderAnalytics;
 const yd=$('#an-yesterday');if(yd)yd.onclick=()=>{const d=analysisDefaultDate();if(from)from.value=d;if(to)to.value=d;rerenderAnalytics()};
 const l7=$('#an-last7');if(l7)l7.onclick=()=>{const d=analysisDefaultDate();if(to)to.value=d;if(from)from.value=addDays(d,-6);rerenderAnalytics()};
 const mo=$('#an-month');if(mo)mo.onclick=()=>{const d=to?.value||analysisDefaultDate();if(from)from.value=monthStart(d);if(to)to.value=d;rerenderAnalytics()};
 const lx=$('#an-latest-xml');if(lx)lx.onclick=()=>{const d=latestXmlDate();if(from)from.value=d;if(to)to.value=d;rerenderAnalytics()};
 const r=$('#analytics-refresh');if(r)r.onclick=async()=>{await refreshAndPatch();updateXmlSelectedUi()};
 const cutBtn=$('#sector-cutover-save');if(cutBtn)cutBtn.onclick=async()=>{const input=$('#sector-cutover-input'),v=input?.value;if(!v)return toast('Informe a data de início do ciclo V3.');const {error}=await sb.from('analytics_settings').update({sector_cutover_date:v,updated_by:session.user.id,updated_at:now()}).eq('org_id',membership.org_id);if(error)return toast(`Falha ao salvar data: ${error.message}`);toast('Data de corte V3 atualizada.');await refreshAndPatch()};
 const choose=$('#xml-choose-btn');if(choose)choose.onclick=openStableXmlPicker;updateXmlSelectedUi();
 const vb=$('#xml-validate-btn');if(vb)vb.onclick=validateXmlZip;const ib=$('#xml-import-btn');if(ib)ib.onclick=importXmlZip;const hb=$('#xml-health-btn');if(hb)hb.onclick=testXmlImportHealth;
 $$('.xml-delete').forEach(b=>b.onclick=()=>deleteXmlImport(b.dataset.id));const da=$('#xml-delete-all');if(da)da.onclick=deleteAllXmlImports;
 const of=$('#opening-form');if(of)of.onsubmit=async e=>{e.preventDefault();try{await saveOpeningStock(of)}catch(x){toast(errText(x))}};
 $$('.map-save').forEach(b=>b.onclick=()=>{const sel=[...document.querySelectorAll('.map-menu')].find(x=>x.dataset.code===b.dataset.code);saveFiscalMapping(b.dataset.code,b.dataset.name,sel?.value)})
}
function openTechSheet(menuId){const i=menuById(menuId),rows=cache.menuComponents.filter(c=>c.menu_item_id===menuId&&c.active!==false);$('#modal-root').innerHTML=`<div class="modal-backdrop"><div class="modal"><div class="panel-head"><div><h2>Ficha técnica de proteínas + setor</h2><small>${esc(i.name||'')} · padrão ${esc(locationLabel(menuSector(menuId)))}</small></div><button id="close-modal" class="icon-btn">×</button></div><div class="panel-body"><form id="component-form" class="form-grid"><input type="hidden" name="menu_item_id" value="${menuId}"><label>Proteína<select name="protein_id" required>${proteinOptions()}</select></label><label>Gramatura por unidade (g)<input name="standard_grams" inputmode="decimal" required></label><label>Estágio consumido<select name="stage"><option value="CLEAN">Limpo</option><option value="PORTIONED">Porcionado</option><option value="PREPARED">Preparado</option><option value="TRIMMED">Pré-limpo</option></select></label><label>Setor de baixa<select name="source_sector">${sectorOptions('',true)}</select></label><label class="full">Observação<input name="notes" placeholder="Ex.: componente sai do Sushi Bar"></label><div class="form-actions full"><button class="btn accent">Adicionar / atualizar</button></div></form><div class="section-title">Componentes</div><div id="component-list">${rows.length?rows.map(c=>`<div class="status-line"><span><b>${esc(proteinName(c.protein_id))}</b><small class="muted" style="display:block">${n(c.standard_grams)} g · ${esc(c.stage||'CLEAN')} · ${esc(locationLabel(componentSector(c,menuId)))}</small></span><button class="small-btn danger-lite comp-delete" data-id="${c.id}">Excluir</button></div>`).join(''):'<div class="empty">Sem componentes adicionais. Enquanto isso, vale a proteína/gramatura e setor principal do produto.</div>'}</div></div></div></div>`;$('#close-modal').onclick=()=>$('#modal-root').innerHTML='';const f=$('#component-form');f.onsubmit=async e=>{e.preventDefault();const d=fd(f),{error}=await sb.rpc('pf_upsert_menu_component_v3',{p_menu_item_id:menuId,p_protein_id:d.protein_id,p_standard_grams:n(d.standard_grams),p_stage:d.stage,p_source_sector:d.source_sector||null,p_notes:d.notes||null});if(error)return toast(error.message);await refreshAndPatch();openTechSheet(menuId)};$$('.comp-delete').forEach(b=>b.onclick=async()=>{if(!confirm('Excluir esta proteína da ficha?'))return;const {error}=await sb.rpc('pf_delete_menu_component',{p_id:b.dataset.id,p_reason:'Exclusão na ficha técnica'});if(error)return toast(error.message);await refreshAndPatch();openTechSheet(menuId)})}
function renderEvidence(){return `${header('Evidências / Fotos','Fotos armazenadas de forma privada no Supabase Storage.')}<div id="evidence-live">${evidenceHtml()}</div>`}
function evidenceRows(){const a=[];const add=(arr,type,qty,pi='photo_item_path',ps='photo_scale_path')=>arr.forEach(r=>{if(r[pi]||r[ps])a.push({type,row:r,qty:n(r[qty]),p1:r[pi],p2:r[ps]})});add(cache.receipts,'Recebimento','weight_kg');add(cache.production,'Produção','actual_use_kg');add(cache.losses,'Perda','qty_kg');add(cache.inventory,'Inventário','counted_kg');add(cache.movements,'Transferência','qty_kg');add(cache.leftovers.filter(isClosingProteinBalance),'Sobra proteína','measured_kg');cache.processing.forEach(r=>a.push({type:'Beneficiamento',row:r,qty:n(r.clean_kg),photos:r.photos||[]}));return a.sort((a,b)=>String(b.row.event_at).localeCompare(String(a.row.event_at))).slice(0,100)}
function evidenceHtml(){const rows=evidenceRows();return `<div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(230px,1fr))">${rows.map((x,i)=>`<article class="report-card"><span class="badge">${x.type}</span><h3>${esc(proteinName(x.row.protein_id))}</h3><p>${fmtDate(x.row.event_date)} · ${kg(x.qty)}</p><button class="btn soft evidence-btn" data-evi="${i}">Ver fotos</button></article>`).join('')||'<div class="empty">Nenhuma evidência.</div>'}</div>`}
function bindEvidence(){$$('.evidence-btn').forEach(b=>b.onclick=()=>openEvidence(Number(b.dataset.evi)))}
async function openEvidence(i){const x=evidenceRows()[i];if(!x)return;const paths=x.photos||[x.p1,x.p2].filter(Boolean);const urls=[];for(const p of paths){const {data,error}=await sb.storage.from('evidence').createSignedUrl(p,3600);if(!error&&data?.signedUrl)urls.push(data.signedUrl)}$('#modal-root').innerHTML=`<div class="modal-backdrop"><div class="modal"><div class="panel-head"><h2>${x.type} · ${esc(proteinName(x.row.protein_id))}</h2><button id="close-modal" class="icon-btn">×</button></div><div class="panel-body gallery">${urls.map(u=>`<img src="${esc(u)}">`).join('')||'<div class="empty">Fotos indisponíveis.</div>'}</div></div></div>`;$('#close-modal').onclick=()=>$('#modal-root').innerHTML=''}

function latestInventoryDate(){return allPhysicalRows(today()).map(r=>String(r.event_date||'')).filter(Boolean).sort().at(-1)||today()}
function renderReports(){const defFrom=analysisDefaultDate(),defTo=analysisDefaultDate();return `${header('Relatórios','Relatórios do ciclo completo: rendimentos, setores, CMV, estoque, perdas e inventário.')}<div class="filters"><label>De<input id="rep-from" type="date" value="${defFrom}"></label><label>Até<input id="rep-to" type="date" value="${defTo}"></label><button id="rep-last-inventory" class="btn soft" type="button">Usar última posição física (${fmtDate(latestInventoryDate())})</button></div><div class="report-grid">${[['RESUMO','Resumo Executivo','KPIs do ciclo e resultado de proteínas.'],['SETORES','Análise por Setor','Sushi Bar, Poke e Cozinha: vendas, consumo, CMV e estoque.'],['RENDIMENTOS','Rendimentos de Beneficiamento','Etapa Central e limpeza final com custos e perdas.'],['CMV','CMV & Margem de Proteínas','Vendas XML, CMV teórico/reconciliado, eficiência e perdas.'],['CONCILIACAO','Conciliação 3 Vias','Consumo físico × produção de proteína apontada × consumo teórico XML, com perdas.'],['MOV_ESTOQUE','Movimentação por Período','Kardex analítico após a base física: entradas, transferências, beneficiamento, perdas, XML e fechamento.'],['SOBRAS_PROTEINA','Sobras de Proteína','Proteína física que permaneceu no fechamento por setor e estágio.'],['ITEM_PROTEINA','Consumo por Item e Proteína','Kg consumidos por item, gramatura, venda associada e CMV.'],['ITENS_CMV','Itens de Venda × Ficha Técnica','Quantidade, setor, gramatura, CMV e margem.'],['ESTOQUE_TOTAL','Estoque Total da Casa','Consolidado por proteína.'],['ESTOQUE_TEORICO','Estoque por Local/Estágio','Central, Produção, Sushi Bar, Poke e Cozinha.'],['POSICAO_INVENTARIO','Posição Física do Inventário','Última contagem física por proteína/local/estágio.'],['INVENTARIO','Inventário + Divergência','Contagem, teórico antes, diferença kg e R$.'],['RECEBIMENTOS','Recebimentos','Entradas, fornecedores, lotes e custos.'],['BENEFICIAMENTO','Beneficiamento','Histórico de transformação.'],['MOVIMENTACOES','Kardex','Transferências entre áreas.'],['PRODUCAO','Produção de Proteínas','Kg de proteína produzida/preparada por setor, sem item de venda.'],['PERDAS','Perdas','Peso, motivo, setor e impacto financeiro.'],['VENDAS_XML','Vendas XML','Itens fiscais importados e mapeamento.'],['COMPLETO','Relatório Completo','Workbook profissional com todas as abas.']].map(x=>`<article class="report-card"><h3>${x[1]}</h3><p>${x[2]}</p><div class="actions"><button class="small-btn report-xlsx" data-report="${x[0]}">XLSX</button><button class="small-btn report-pdf" data-report="${x[0]}">PDF</button></div></article>`).join('')}</div>`}
function renderUsers(){return `${header('Usuários','Crie acessos com senha e defina perfis.')}<div class="two-col"><section class="panel"><div class="panel-head"><h2>Novo usuário</h2></div><div class="panel-body"><form id="new-user-form" class="form-grid"><label class="full">Nome<input name="display_name" required></label><label class="full">E-mail<input name="email" type="email" required></label><label>Senha temporária<input name="password" type="password" minlength="8" required></label><label>Perfil<select name="role"><option value="PRODUCTION">Produção</option><option value="MANAGER">Gerente</option><option value="AUDITOR">Auditor</option><option value="ADMIN">Administrador</option></select></label><div class="form-actions full"><button class="btn accent" type="submit">Criar acesso</button></div></form></div></section><section class="panel"><div class="panel-head"><h2>Equipe</h2></div><div id="users-live" class="panel-body">${usersHtml()}</div></section></div>`}
function usersHtml(){return cache.users.length?`<div class="status-list">${cache.users.map(u=>`<div class="status-line"><div><b>${esc(u.display_name||u.email)}</b><small class="muted" style="display:block">${esc(u.email||'')}</small></div><div class="actions"><select class="user-role" data-id="${u.id}"><option ${u.role==='PRODUCTION'?'selected':''} value="PRODUCTION">Produção</option><option ${u.role==='MANAGER'?'selected':''} value="MANAGER">Gerente</option><option ${u.role==='AUDITOR'?'selected':''} value="AUDITOR">Auditor</option><option ${u.role==='ADMIN'?'selected':''} value="ADMIN">Admin</option><option ${u.role==='SUPER_ADMIN'?'selected':''} value="SUPER_ADMIN">Super Admin</option></select><button class="small-btn user-save" data-id="${u.id}">Salvar</button><button class="small-btn user-toggle" data-id="${u.id}" data-active="${u.active}">${u.active?'Bloquear':'Reativar'}</button></div></div>`).join('')}</div>`:'<div class="empty">Nenhum usuário carregado.</div>'}

function launchActions(kind,id){return isAdmin()?`<td class="row-actions"><button class="small-btn edit-launch" data-kind="${kind}" data-id="${id}">✎ Editar</button><button class="small-btn danger-lite delete-launch" data-kind="${kind}" data-id="${id}">🗑 Apagar</button></td>`:''}
function historyHtml(kind){let arr=[],cols='',heads=[];if(kind==='receipts'){arr=cache.receipts.slice(-15).reverse();heads=['Data','Proteína','Fornecedor','Lote','Peso','Valor'];cols=arr.map(r=>`<tr><td>${fmtDate(r.event_date)}</td><td>${esc(proteinName(r.protein_id))}</td><td>${esc(r.supplier)}</td><td>${esc(r.lot)}</td><td>${kg(r.weight_kg)}</td><td>${brl(r.total_value)}</td>${launchActions(kind,r.id)}</tr>`).join('')}else if(kind==='processing'){arr=cache.processing.slice(-15).reverse();heads=['Data','Proteína','Etapa','Entrada','Saída','Rendimento'];cols=arr.map(r=>`<tr><td>${fmtDate(r.event_date)}</td><td>${esc(proteinName(r.protein_id))}</td><td>${r.operation_type==='CENTRAL_TRIM'?'Central · Pré-limpeza':r.operation_type==='PRODUCTION_CLEAN'?'Produção · Limpeza final':'Legado'}</td><td>${kg(r.input_kg||r.whole_kg)}</td><td>${kg(r.output_kg||r.clean_kg)}</td><td>${pct(r.stage_yield_pct||r.yield_total_pct)}</td>${launchActions(kind,r.id)}</tr>`).join('')}else if(kind==='movements'){arr=cache.movements.slice(-15).reverse();heads=['Data','Proteína','Estágio','Movimento','Quantidade'];cols=arr.map(r=>`<tr><td>${fmtDate(r.event_date)}</td><td>${esc(proteinName(r.protein_id))}</td><td>${esc(r.stage)}</td><td>${esc(locationLabel(r.from_location))} → ${esc(locationLabel(r.to_location))}</td><td>${kg(r.qty_kg)}</td>${launchActions(kind,r.id)}</tr>`).join('')}else if(kind==='production'){arr=cache.production.slice(-15).reverse();heads=['Data','Setor','Proteína','Estágio','Tipo','Kg produção'];cols=arr.map(r=>{const proteinMode=isProteinProduction(r),q=proteinMode?n(r.produced_protein_kg!=null?r.produced_protein_kg:r.actual_use_kg):n(r.actual_use_kg);return `<tr><td>${fmtDate(r.event_date)}</td><td>${esc(locationLabel(r.location))}</td><td><b>${esc(proteinName(r.protein_id))}</b>${!proteinMode&&r.menu_item_id?`<small class="muted" style="display:block">Legado: ${esc(r.item_name||menuById(r.menu_item_id).name)}</small>`:''}</td><td>${esc(r.stage||'CLEAN')}</td><td>${esc(proteinMode?(r.production_operation||'PROTEÍNA'):'LEGADO ITEM')}</td><td><b>${kg(q)}</b></td>${launchActions(kind,r.id)}</tr>`}).join('')}else if(kind==='leftovers'){arr=cache.leftovers.filter(isClosingProteinBalance).slice(-15).reverse();heads=['Data','Proteína','Setor','Estágio','Sobra final'];cols=arr.map(r=>`<tr><td>${fmtDate(r.event_date)}</td><td><b>${esc(proteinName(r.protein_id))}</b></td><td>${esc(locationLabel(r.location))}</td><td>${esc(r.stage||'CLEAN')}</td><td><b>${kg(r.measured_kg)}</b></td>${launchActions(kind,r.id)}</tr>`).join('')}else if(kind==='losses'){arr=cache.losses.slice(-15).reverse();heads=['Data','Proteína','Local','Perda','Motivo','Valor'];cols=arr.map(r=>`<tr><td>${fmtDate(r.event_date)}</td><td>${esc(proteinName(r.protein_id))}</td><td>${esc(locationLabel(r.location))}</td><td>${kg(r.qty_kg)}</td><td>${esc(r.cause)}</td><td>${brl(r.loss_value)}</td>${launchActions(kind,r.id)}</tr>`).join('')}else if(kind==='inventory'){arr=cache.inventory.slice(-15).reverse();heads=['Data','Proteína','Local','Estágio','Físico','Teórico antes','Variação'];cols=arr.map(r=>`<tr><td>${fmtDate(r.event_date)}</td><td>${esc(proteinName(r.protein_id))}</td><td>${esc(locationLabel(r.location))}</td><td>${esc(r.stage)}</td><td>${kg(r.counted_kg)}</td><td>${r.theoretical_before_kg==null?'—':kg(r.theoretical_before_kg)}</td><td class="${n(r.variance_kg)<-.001?'bad':Math.abs(n(r.variance_kg))>.001?'warn':'ok'}">${r.variance_kg==null?'—':kg(r.variance_kg)}</td>${launchActions(kind,r.id)}</tr>`).join('')}else return '<div class="empty">Sem registros.</div>';if(isAdmin())heads.push('Ações');return tableHistory(heads,cols)}
function tableHistory(head,body){return body?`<div class="table-wrap"><table class="data-table"><thead><tr>${head.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${body}</tbody></table></div>`:'<div class="empty">Nenhum lançamento.</div>'}

const LAUNCH_META={
 receipts:{table:'receipts',cache:'receipts',title:'Recebimento'},
 processing:{table:'processing_batches',cache:'processing',title:'Beneficiamento'},
 movements:{table:'stock_movements',cache:'movements',title:'Transferência'},
 production:{table:'production_batches',cache:'production',title:'Produção'},
 leftovers:{table:'leftovers',cache:'leftovers',title:'Sobra'},
 losses:{table:'losses',cache:'losses',title:'Perda'},
 inventory:{table:'inventory_counts',cache:'inventory',title:'Inventário'}
};
function launchRecord(kind,id){const m=LAUNCH_META[kind];return m?(cache[m.cache]||[]).find(x=>x.id===id):null}
function selectOpts(items,value){return items.map(([v,l])=>`<option value="${v}" ${String(v)===String(value)?'selected':''}>${l}</option>`).join('')}
function proteinEditOptions(value){return `<option value="">Selecione...</option>`+cache.proteins.map(p=>`<option value="${p.id}" ${p.id===value?'selected':''}>${esc(p.name)}</option>`).join('')}
function menuEditOptions(value){return `<option value="">Selecione...</option>`+cache.menuItems.map(m=>`<option value="${m.id}" ${m.id===value?'selected':''}>${esc(m.name)}</option>`).join('')}
function editFields(kind,r){const commonDate=`<label>Data<input name="event_date" type="date" value="${esc(r.event_date||today())}" required></label>`;if(kind==='receipts')return `${commonDate}<label>Proteína<select name="protein_id" required>${proteinEditOptions(r.protein_id)}</select></label><label>Fornecedor<input name="supplier" value="${esc(r.supplier||'')}" required></label><label>Lote<input name="lot" value="${esc(r.lot||'')}" required></label><label>Validade<input name="expiry" type="date" value="${esc(r.expiry||'')}"></label><label>Temperatura °C<input name="temperature_c" inputmode="decimal" value="${esc(r.temperature_c??'')}"></label><label>Peso kg<input name="weight_kg" inputmode="decimal" value="${esc(r.weight_kg??'')}" required></label><label>Custo/kg<input name="cost_kg" inputmode="decimal" value="${esc(r.cost_kg??'')}"></label><input type="hidden" name="location" value="CENTRAL"><label class="full">Observação<textarea name="notes">${esc(r.notes||'')}</textarea></label>`;if(kind==='processing')return `${commonDate}<label>Proteína<select name="protein_id" required>${proteinEditOptions(r.protein_id)}</select></label><label>Lote<input name="lot" value="${esc(r.lot||'')}" required></label><label>Etapa<input value="${esc(r.operation_type||'LEGACY_FULL')}" disabled></label><label>Entrada kg<input name="input_kg" inputmode="decimal" value="${esc(r.input_kg??r.whole_kg??'')}" required></label><label>Saída kg<input name="output_kg" inputmode="decimal" value="${esc(r.output_kg??r.clean_kg??'')}" required></label><label class="full">Observação<textarea name="notes">${esc(r.notes||'')}</textarea></label>`;if(kind==='movements')return `${commonDate}<label>Proteína<select name="protein_id" required>${proteinEditOptions(r.protein_id)}</select></label><label>Estágio<select name="stage">${selectOpts([['WHOLE','Inteiro'],['TRIMMED','Pré-limpo'],['CLEAN','Limpo'],['PORTIONED','Porcionado'],['PREPARED','Preparado']],r.stage)}</select></label><label>Origem<select name="from_location">${locationOptions(r.from_location,true,true,true)}</select></label><label>Destino<select name="to_location">${locationOptions(r.to_location,true,true,true)}</select></label><label>Quantidade kg<input name="qty_kg" inputmode="decimal" value="${esc(r.qty_kg??'')}" required></label><label>Motivo<input name="reason" value="${esc(r.reason||'')}"></label>`;if(kind==='production'){if(isProteinProduction(r))return `${commonDate}<label>Proteína<select name="protein_id" required>${proteinEditOptions(r.protein_id)}</select></label><label>Setor<select name="location">${sectorOptions(r.location||'SUSHI_BAR')}</select></label><label>Estágio<select name="stage">${selectOpts([['CLEAN','Limpo'],['PORTIONED','Porcionado'],['PREPARED','Preparado']],r.stage||'CLEAN')}</select></label><label>Tipo<select name="production_operation">${selectOpts([['PORCIONAMENTO','Porcionamento'],['MISE_EN_PLACE','Mise en place / pré-preparo'],['PREPARACAO','Preparação do setor'],['OUTRO','Outro']],r.production_operation||'PREPARACAO')}</select></label><label>Peso produzido/preparado kg<input name="produced_protein_kg" inputmode="decimal" value="${esc(r.produced_protein_kg??r.actual_use_kg??'')}" required></label><label class="full">Observação<textarea name="notes">${esc(r.notes||'')}</textarea></label>`;return `${commonDate}<div class="warning full">Registro legado por item. Para preservar o histórico original, apenas campos gerais permanecem visíveis.</div><label>Proteína<select name="protein_id" required>${proteinEditOptions(r.protein_id)}</select></label><label>Setor<select name="location">${sectorOptions(r.location||'SUSHI_BAR')}</select></label><label>Peso real legado kg<input name="actual_use_kg" inputmode="decimal" value="${esc(r.actual_use_kg??'')}" required></label><label class="full">Observação<textarea name="notes">${esc(r.notes||'')}</textarea></label>`}if(kind==='leftovers')return `${commonDate}<label>Proteína<select name="protein_id" required>${proteinEditOptions(r.protein_id)}</select></label><label>Setor / local<select name="location">${locationOptions(r.location||'SUSHI_BAR',true,true,false)}</select></label><label>Estágio<select name="stage">${selectOpts([['WHOLE','Inteiro'],['TRIMMED','Pré-limpo'],['CLEAN','Limpo'],['PORTIONED','Porcionado'],['PREPARED','Preparado']],r.stage||'CLEAN')}</select></label><label>Peso que sobrou kg<input name="measured_kg" inputmode="decimal" value="${esc(r.measured_kg??'')}" required></label><label class="full">Observação<textarea name="notes">${esc(r.notes||'')}</textarea></label>`;if(kind==='losses')return `${commonDate}<label>Proteína<select name="protein_id" required>${proteinEditOptions(r.protein_id)}</select></label><label>Local<select name="location">${locationOptions(r.location,true,true,true)}</select></label><label>Estágio<select name="stage">${selectOpts([['WHOLE','Inteiro'],['TRIMMED','Pré-limpo'],['CLEAN','Limpo'],['PORTIONED','Porcionado'],['PREPARED','Preparado']],r.stage)}</select></label><label>Peso perdido kg<input name="qty_kg" inputmode="decimal" value="${esc(r.qty_kg??'')}" required></label><label>Motivo<input name="cause" value="${esc(r.cause||'')}" required></label><label>Custo/kg<input name="cost_kg" inputmode="decimal" value="${esc(r.cost_kg??'')}"></label><label class="full">Observação<textarea name="notes">${esc(r.notes||'')}</textarea></label>`;if(kind==='inventory')return `${commonDate}<label>Proteína<select name="protein_id" required>${proteinEditOptions(r.protein_id)}</select></label><label>Local<select name="location">${locationOptions(r.location,true,true,true)}</select></label><label>Estágio<select name="stage">${selectOpts([['WHOLE','Inteiro'],['TRIMMED','Pré-limpo'],['CLEAN','Limpo'],['PORTIONED','Porcionado'],['PREPARED','Preparado']],r.stage)}</select></label><label>Peso físico kg<input name="counted_kg" inputmode="decimal" value="${esc(r.counted_kg??'')}" required></label><label>Custo/kg<input name="cost_kg" inputmode="decimal" value="${esc(r.cost_kg??'')}"></label><label class="full">Observação<textarea name="notes">${esc(r.notes||'')}</textarea></label>`;return ''}
function closeLaunchModal(){document.querySelector('#launch-edit-modal')?.remove()}
function openLaunchEdit(kind,id){if(!isAdmin())return toast('Somente Administrador/SUPER_ADMIN pode alterar lançamentos.');const r=launchRecord(kind,id),m=LAUNCH_META[kind];if(!r||!m)return toast('Lançamento não localizado.');document.body.insertAdjacentHTML('beforeend',`<div id="launch-edit-modal" class="modal-backdrop"><div class="modal"><div class="panel-head"><div><h2>Editar ${m.title}</h2><small>ID ${esc(id)}</small></div><button type="button" class="icon-btn" id="close-launch-modal">✕</button></div><div class="panel-body"><div class="warning">As fotos existentes serão preservadas. Toda alteração fica registrada na Auditoria.</div><form id="launch-edit-form" class="form-grid">${editFields(kind,r)}<label class="full">Motivo da alteração<textarea name="change_reason" required minlength="3" placeholder="Ex.: correção de peso digitado incorretamente"></textarea></label><div class="form-actions full"><button type="button" class="btn secondary" id="cancel-launch-edit">Cancelar</button><button type="submit" class="btn accent">Salvar alteração</button></div></form></div></div></div>`);$('#close-launch-modal').onclick=closeLaunchModal;$('#cancel-launch-edit').onclick=closeLaunchModal;$('#launch-edit-modal').addEventListener('click',e=>{if(e.target.id==='launch-edit-modal')closeLaunchModal()});$('#launch-edit-form').onsubmit=e=>{e.preventDefault();saveLaunchEdit(kind,id,e.currentTarget)}}
function editPatch(kind,f){const d=fd(f),p={event_date:d.event_date};if(kind==='receipts')Object.assign(p,{protein_id:d.protein_id,supplier:d.supplier,lot:d.lot,expiry:d.expiry||null,temperature_c:d.temperature_c||null,weight_kg:n(d.weight_kg),cost_kg:n(d.cost_kg),location:'CENTRAL',notes:d.notes||null});if(kind==='processing'){const old=launchRecord('processing',f.closest('#launch-edit-modal')?.querySelector('[data-id]')?.dataset.id);Object.assign(p,{protein_id:d.protein_id,lot:d.lot,input_kg:n(d.input_kg),output_kg:n(d.output_kg),notes:d.notes||null})}if(kind==='movements')Object.assign(p,{protein_id:d.protein_id,stage:d.stage,from_location:d.from_location,to_location:d.to_location,qty_kg:n(d.qty_kg),reason:d.reason||null});if(kind==='production'){const rec=launchRecord('production',f.closest('#launch-edit-modal')?.querySelector('[data-id]')?.dataset.id);if(isProteinProduction(rec))Object.assign(p,{menu_item_id:null,item_name:null,protein_id:d.protein_id,location:d.location,stage:d.stage||'CLEAN',production_kind:'PROTEIN',production_operation:d.production_operation||'PREPARACAO',produced_protein_kg:n(d.produced_protein_kg),actual_use_kg:n(d.produced_protein_kg),qty_produced:0,standard_g:0,theoretical_use_kg:0,variance_kg:0,variance_pct:0,stock_effect:false,notes:d.notes||null});else Object.assign(p,{protein_id:d.protein_id,location:d.location,actual_use_kg:n(d.actual_use_kg),notes:d.notes||null})};if(kind==='leftovers')Object.assign(p,{menu_item_id:null,protein_id:d.protein_id||null,location:d.location,stage:d.stage||'CLEAN',closing_balance:true,qty_units:0,standard_g:0,theoretical_kg:0,measured_kg:n(d.measured_kg),destination:'ESTOQUE_FECHAMENTO',notes:d.notes||null});if(kind==='losses')Object.assign(p,{protein_id:d.protein_id,location:d.location,stage:d.stage,qty_kg:n(d.qty_kg),cause:d.cause,cost_kg:n(d.cost_kg),notes:d.notes||null});if(kind==='inventory')Object.assign(p,{protein_id:d.protein_id,location:d.location,stage:d.stage,counted_kg:n(d.counted_kg),cost_kg:n(d.cost_kg),notes:d.notes||null});return p}
async function saveLaunchEdit(kind,id,f){const reason=String(f.change_reason.value||'').trim();if(reason.length<3)return toast('Informe o motivo da alteração.');if(kind==='processing'&&launchRecord(kind,id)?.operation_type&&launchRecord(kind,id)?.operation_type!=='LEGACY_FULL')return toast('Para preservar a cadeia de custos do ciclo V3, apague a etapa de beneficiamento e lance novamente em vez de editar pesos.');const btn=f.querySelector('button[type="submit"]');btn.disabled=true;const old=btn.textContent;btn.textContent='Salvando…';try{await rpcRest('pf_update_launch',{p_table:LAUNCH_META[kind].table,p_id:id,p_patch:editPatch(kind,f),p_reason:reason});closeLaunchModal();await refreshAndPatch();toast('Lançamento alterado e registrado na auditoria.')}catch(e){console.error(e);toast(`Não foi possível alterar: ${errText(e)}`)}finally{btn.disabled=false;btn.textContent=old}}
function launchPhotoPaths(kind,r){if(kind==='processing')return (Array.isArray(r.photos)?r.photos:[]).filter(Boolean);return [r.photo_item_path,r.photo_scale_path].filter(Boolean)}
async function deleteLaunch(kind,id){if(!isAdmin())return toast('Somente Administrador/SUPER_ADMIN pode apagar lançamentos.');const r=launchRecord(kind,id),m=LAUNCH_META[kind];if(!r||!m)return toast('Lançamento não localizado.');const reason=prompt(`Motivo para APAGAR este lançamento de ${m.title}:`,'Lançamento de teste / correção');if(reason===null)return;if(String(reason).trim().length<3)return toast('Informe um motivo para apagar.');if(!confirm(`Confirma apagar definitivamente este lançamento?\n\n${m.title} · ${fmtDate(r.event_date)}\n\nA ação ficará registrada na Auditoria.`))return;try{const paths=launchPhotoPaths(kind,r);await rpcRest('pf_delete_launch',{p_table:m.table,p_id:id,p_reason:String(reason).trim()});if(paths.length){const {error}=await sb.storage.from('evidence').remove(paths);if(error)console.warn('Registro apagado; falha ao remover arquivos',error)}await refreshAndPatch();toast('Lançamento apagado. Auditoria preservada.')}catch(e){console.error(e);toast(`Não foi possível apagar: ${errText(e)}`)}}
function bindLaunchActions(){$$('.edit-launch').forEach(b=>b.onclick=()=>openLaunchEdit(b.dataset.kind,b.dataset.id));$$('.delete-launch').forEach(b=>b.onclick=()=>deleteLaunch(b.dataset.kind,b.dataset.id))}

function bindRoute(){
 bindNav();const forms={"receipt-form":saveReceipt,"processing-form":saveProcessing,"movement-form":saveMovement,"production-form":saveProduction,"leftover-form":saveLeftover,"loss-form":saveLoss,"inventory-form":saveInventory,"new-user-form":createUser};
 Object.entries(forms).forEach(([id,fn])=>{const f=$(`#${id}`);if(f)f.onsubmit=async e=>{e.preventDefault();try{await fn(f)}catch(err){console.error('Falha no formulário',id,err);toast(`ERRO: ${errText(err)}`)}}});
 if($('#processing-form'))bindProcessingCalc();if($('#production-form'))bindProductionCalc();const invDate=$('#inv-date');if(invDate)invDate.onchange=()=>{const box=document.querySelector('.inventory-coverage');if(box)box.innerHTML=inventoryCoverageHtml(invDate.value)};bindPhotoInputs();if($('#refresh-btn'))$('#refresh-btn').onclick=refreshAndPatch;bindEvidence();
 $$('.report-xlsx').forEach(b=>b.onclick=()=>exportXlsx(b.dataset.report));$$('.report-pdf').forEach(b=>b.onclick=()=>exportPdf(b.dataset.report));const rli=$('#rep-last-inventory');if(rli)rli.onclick=()=>{const d=latestInventoryDate();$('#rep-from').value=d;$('#rep-to').value=d;toast(`Período ajustado para o último inventário: ${fmtDate(d)}`)};bindUserActions();bindLaunchActions();if(route==='catalog'&&isAdmin())bindProductActions();if(route==='analytics')bindAnalyticsActions()
}
function bindProcessingCalc(){const f=$('#processing-form'),out=$('#processing-calc'),typ=$('#processing-type'),note=$('#processing-location-note'),inLab=$('#processing-input-label'),outLab=$('#processing-output-label');const go=()=>{const type=typ.value,input=n(f.input_kg.value),output=n(f.output_kg.value),pid=f.protein_id.value,date=f.event_date.value||today(),inputStage=type==='CENTRAL_TRIM'?'WHOLE':'TRIMMED',inputCost=stageCost(pid,inputStage,date),outputCost=output>0?input*inputCost/output:0,loss=Math.max(0,input-output),y=input?output/input:0;if(type==='CENTRAL_TRIM'){note.innerHTML='<b>Estoque:</b> Central · Inteiro → Pré-limpo';inLab.childNodes[0].textContent='Peso inteiro de entrada kg';outLab.childNodes[0].textContent='Peso pré-limpo de saída kg'}else{note.innerHTML='<b>Estoque:</b> Produção · Pré-limpo → Limpo';inLab.childNodes[0].textContent='Peso pré-limpo de entrada kg';outLab.childNodes[0].textContent='Peso limpo de saída kg'}out.innerHTML=`<div><small>Perda da etapa</small><b>${kg(loss)}</b></div><div><small>Perda %</small><b>${input?pct(loss/input):'—'}</b></div><div><small>Rendimento etapa</small><b>${input?pct(y):'—'}</b></div><div><small>Custo entrada</small><b>${brl(inputCost)}/kg</b></div><div><small>Custo saída</small><b>${brl(outputCost)}/kg</b></div><div><small>Impacto perda</small><b>${brl(loss*inputCost)}</b></div>`};f.addEventListener('input',go);f.addEventListener('change',go);go()}
function bindProductionCalc(){const f=$('#production-form'),out=$('#production-calc'),pid=$('#prod-protein'),sector=$('#prod-sector');const go=()=>{const q=n(f.produced_protein_kg.value),cost=pid?.value?stageCost(pid.value,f.stage?.value||'CLEAN',f.event_date?.value||today()):0;out.innerHTML=`<div><small>Setor</small><b>${locationLabel(sector?.value)}</b></div><div><small>Produção apontada</small><b>${kg(q)}</b></div><div><small>Custo/kg</small><b>${brl(cost)}</b></div><div><small>Valor da proteína</small><b>${brl(q*cost)}</b></div><div><small>Efeito no estoque</small><b>Somente análise</b></div>`};f.addEventListener('input',go);f.addEventListener('change',go);go()}
function bindLeftoverAuto(){/* V3.12: sobra é proteína física; não depende de item de venda. */}
function bindPhotoInputs(){
  $$('.photo-box input[type="file"]').forEach(inp=>{inp.onchange=()=>{const box=inp.closest('.photo-box'),img=box?.querySelector('.photo-preview'),txt=box?.querySelector('.photo-selected'),ph=box?.querySelector('.photo-placeholder'),file=inp.files?.[0];if(!box)return;if(file){if(img){img.src=URL.createObjectURL(file);img.hidden=false}if(ph)ph.hidden=true;if(txt)txt.textContent=`✓ ${file.name||'Foto pronta'} · ${(file.size/1024/1024).toFixed(1)} MB`;box.classList.add('has-photo')}else{if(img){img.removeAttribute('src');img.hidden=true}if(ph)ph.hidden=false;if(txt)txt.textContent='Nenhuma foto selecionada';box.classList.remove('has-photo')}}})
}
async function compress(file){if(!file)return null;try{const bmp=await createImageBitmap(file),max=1280,scale=Math.min(1,max/Math.max(bmp.width,bmp.height)),c=document.createElement('canvas');c.width=Math.max(1,Math.round(bmp.width*scale));c.height=Math.max(1,Math.round(bmp.height*scale));c.getContext('2d').drawImage(bmp,0,0,c.width,c.height);const blob=await new Promise(r=>c.toBlob(r,'image/jpeg',.78));return blob||file}catch{return file}}
function photoDb(){return new Promise((resolve,reject)=>{const req=indexedDB.open(PHOTO_DB,1);req.onupgradeneeded=()=>{const db=req.result;if(!db.objectStoreNames.contains(PHOTO_STORE))db.createObjectStore(PHOTO_STORE,{keyPath:'key'})};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
async function photoQueuePut(item){const db=await photoDb();return new Promise((resolve,reject)=>{const tx=db.transaction(PHOTO_STORE,'readwrite');tx.objectStore(PHOTO_STORE).put(item);tx.oncomplete=()=>{db.close();resolve()};tx.onerror=()=>{db.close();reject(tx.error)}})}
async function photoQueueDelete(key){const db=await photoDb();return new Promise((resolve,reject)=>{const tx=db.transaction(PHOTO_STORE,'readwrite');tx.objectStore(PHOTO_STORE).delete(key);tx.oncomplete=()=>{db.close();resolve()};tx.onerror=()=>{db.close();reject(tx.error)}})}
async function photoQueueAll(){const db=await photoDb();return new Promise((resolve,reject)=>{const tx=db.transaction(PHOTO_STORE,'readonly'),req=tx.objectStore(PHOTO_STORE).getAll();req.onsuccess=()=>{db.close();resolve(req.result||[])};req.onerror=()=>{db.close();reject(req.error)}})}
function photoPath(table,id,label){const d=today().split('-');return `${membership.org_id}/${membership.default_unit_id}/${d[0]}/${d[1]}/${d[2]}/${table}/${id}/${label}.jpg`}
async function enqueuePhoto(file,table,id,label,column,index=null){if(!file)throw new Error(`Foto obrigatória: ${label}`);const blob=await compress(file),path=photoPath(table,id,label),key=`${table}:${id}:${label}`;await photoQueuePut({key,table,id,label,column,index,path,blob,org_id:membership.org_id,unit_id:membership.default_unit_id,created_at:now()});return key}
async function updatePhotoRecord(item){if(item.table==='receipts'){const kind=item.column==='photo_item_path'?'item':'scale';const {error}=await sb.rpc('pf_attach_receipt_photo',{p_receipt_id:item.id,p_kind:kind,p_path:item.path});if(error)throw error;return}if(item.table==='processing_batches'){const {data,error}=await sb.from(item.table).select('photos').eq('id',item.id).single();if(error)throw error;const arr=Array.isArray(data.photos)?[...data.photos]:[];arr[item.index]=item.path;const done=arr.filter(Boolean).length>=4;const {error:u}=await sb.from(item.table).update({photos:arr,photo_status:done?'OK':'PENDING',photo_error:null}).eq('id',item.id);if(u)throw u;return}const patch={[item.column]:item.path,photo_error:null};const {data,error}=await sb.from(item.table).select('photo_item_path,photo_scale_path').eq('id',item.id).single();if(error)throw error;const itemPath=item.column==='photo_item_path'?item.path:data.photo_item_path,scalePath=item.column==='photo_scale_path'?item.path:data.photo_scale_path;if(itemPath&&scalePath)patch.photo_status='OK';const {error:u}=await sb.from(item.table).update(patch).eq('id',item.id);if(u)throw u}
async function uploadQueueItem(item){const {error}=await sb.storage.from('evidence').upload(item.path,item.blob,{contentType:'image/jpeg',upsert:true});if(error)throw error;await updatePhotoRecord(item);await photoQueueDelete(item.key)}
async function flushPhotoQueue(recordId=null){if(!sb||!session||!membership||!navigator.onLine)return;const all=await photoQueueAll(),items=recordId?all.filter(x=>x.id===recordId):all;for(const item of items){try{await uploadQueueItem(item)}catch(e){console.warn('Foto pendente',item.key,e);try{await sb.from(item.table).update({photo_status:'PENDING',photo_error:errText(e).slice(0,500)}).eq('id',item.id)}catch{}}}}
function fd(f){return Object.fromEntries(new FormData(f).entries())}
async function saveCloud(form,table,row,photoSpec,success,photosRequired=true){assertOnline();const btn=form.querySelector('button[type="submit"]')||form.querySelector('button');if(!btn)throw new Error('Botão Salvar não encontrado no formulário.');btn.disabled=true;const original=btn.textContent;btn.textContent='Gravando dados…';const id=row.id||uid();row.id=id;try{const provided=photoSpec.filter(p=>form.elements[p.field]?.files?.[0]);if(photosRequired&&provided.length!==photoSpec.length){const missing=photoSpec.find(p=>!form.elements[p.field]?.files?.[0]);throw new Error(`Tire/seleciona a ${missing?.label||'foto'} antes de salvar.`)}row.photo_status=photosRequired?'PENDING':(provided.length?'PENDING':'OK');row.photo_error=null;for(const p of photoSpec)row[p.column]=null;const {error}=await sb.from(table).insert(row);if(error)throw error;if(provided.length){for(const p of provided)await enqueuePhoto(form.elements[p.field].files[0],table,id,p.label,p.column);btn.textContent='Enviando fotos…';await flushPhotoQueue(id);if(!photosRequired){await sb.from(table).update({photo_status:'OK',photo_error:null}).eq('id',id)}const {data:check}=await sb.from(table).select('photo_status').eq('id',id).single();if(check?.photo_status==='OK')toast(`${success}. Dados salvos${provided.length?' e foto(s) anexada(s)':' sem fotos'}.`);else toast(`${success}. DADOS SALVOS; foto(s) pendente(s) e serão reenviadas automaticamente.`)}else{toast(`${success}. Gravado sem fotos.`)}form.reset();bindPhotoInputs();await refreshAndPatch();return true}catch(e){console.error(e);toast(`NÃO SALVO: ${errText(e)}`);return false}finally{btn.disabled=false;btn.textContent=original}}
const base=(eventDate=today())=>({org_id:membership.org_id,unit_id:membership.default_unit_id,event_at:now(),event_date:eventDate||today(),created_by:session.user.id});
async function rpcRest(name,args){
  const {data:{session:liveSession},error:se}=await sb.auth.getSession();
  if(se)throw new Error(`SESSÃO: ${se.message}`);
  if(!liveSession?.access_token)throw new Error('SESSÃO: usuário não autenticado ou sessão expirada. Saia e entre novamente.');
  const res=await fetch(`${CFG.supabaseUrl}/rest/v1/rpc/${name}`,{
    method:'POST',
    headers:{
      apikey:CFG.supabaseAnonKey,
      Authorization:`Bearer ${liveSession.access_token}`,
      'Content-Type':'application/json'
    },
    body:JSON.stringify(args||{})
  });
  const text=await res.text();
  if(!res.ok)throw new Error(`RPC ${name} HTTP ${res.status}: ${text||res.statusText}`);
  if(!text)return null;
  try{return JSON.parse(text)}catch{return text.replace(/^"|"$/g,'')}
}
function photoExt(file){
  const t=String(file?.type||'').toLowerCase();
  if(t.includes('png'))return 'png';
  if(t.includes('webp'))return 'webp';
  if(t.includes('heic'))return 'heic';
  if(t.includes('heif'))return 'heif';
  return 'jpg';
}
async function uploadReceiptPhotoDirect(file,id,label,kind){
  const d=today().split('-'),ext=photoExt(file);
  const path=`${membership.org_id}/${membership.default_unit_id}/${d[0]}/${d[1]}/${d[2]}/receipts/${id}/${label}.${ext}`;
  const {error}=await sb.storage.from('evidence').upload(path,file,{contentType:file.type||'image/jpeg',upsert:true});
  if(error)throw new Error(`STORAGE ${label}: ${error.message}`);
  await rpcRest('pf_attach_receipt_photo',{p_receipt_id:id,p_kind:kind,p_path:path});
  return path;
}
async function saveReceipt(f){
  assertOnline();
  const d=fd(f),btn=f.querySelector('button[type="submit"]')||f.querySelector('button');
  if(!btn)throw new Error('Botão Salvar não encontrado.');
  const photoItem=f.elements.photo_item?.files?.[0],photoScale=f.elements.photo_scale?.files?.[0];
  if(!photoItem||!photoScale){opStatus('Selecione/tire as duas fotos antes de salvar.');return}
  if(!d.protein_id){opStatus('Selecione a proteína.');return}
  if(!String(d.supplier||'').trim()){opStatus('Informe o fornecedor.');return}
  if(!String(d.lot||'').trim()){opStatus('Informe o lote.');return}
  if(n(d.weight_kg)<=0){opStatus('Informe um peso maior que zero.');return}
  btn.disabled=true;const old=btn.textContent;
  try{
    let id=f.dataset.savedReceiptId||'';
    if(!id){
      btn.textContent='1/4 Validando sessão…';
      opStatus('Etapa 1/4: validando login e gravando diretamente na API do Supabase…');
      const cost=n(d.cost_kg)||proteinCost(d.protein_id);
      const out=await rpcRest('pf_create_receipt',{
        p_protein_id:d.protein_id,
        p_supplier:String(d.supplier).trim(),
        p_lot:String(d.lot).trim(),
        p_weight_kg:n(d.weight_kg),
        p_expiry:d.expiry||null,
        p_temperature_c:d.temperature_c?n(d.temperature_c):null,
        p_location:d.location||'CENTRAL',
        p_cost_kg:cost,
        p_notes:d.notes||null,
        p_event_date:d.event_date||today()
      });
      id=String(out||'').replace(/^"|"$/g,'');
      if(!/^[0-9a-f-]{36}$/i.test(id))throw new Error(`BANCO: retorno inesperado da RPC: ${String(out)}`);
      f.dataset.savedReceiptId=id;
      btn.textContent='2/4 Confirmando banco…';
      const {data:confirmed,error:qe}=await sb.from('receipts').select('id,supplier,lot,weight_kg,photo_status').eq('id',id).maybeSingle();
      if(qe)throw new Error(`CONFIRMAÇÃO: ${qe.message}`);
      if(!confirmed)throw new Error('CONFIRMAÇÃO: o ID foi devolvido, mas o registro não foi localizado em receipts.');
      opStatus(`BANCO CONFIRMADO ✓ ID ${id} · ${confirmed.supplier} · lote ${confirmed.lot}. Agora enviando fotos.`,'ok');
    }
    btn.textContent='3/4 Foto produto…';
    opStatus(`BANCO CONFIRMADO ✓ ID ${id}. Enviando foto da proteína…`,'ok');
    await uploadReceiptPhotoDirect(photoItem,id,'produto','item');
    btn.textContent='4/4 Foto balança…';
    opStatus(`BANCO CONFIRMADO ✓ ID ${id}. Foto do produto OK. Enviando foto da balança…`,'ok');
    await uploadReceiptPhotoDirect(photoScale,id,'balanca','scale');
    const {data:check,error:ce}=await sb.from('receipts').select('id,photo_status,photo_item_path,photo_scale_path,photo_error').eq('id',id).maybeSingle();
    if(ce)throw new Error(`CONFIRMAÇÃO FINAL: ${ce.message}`);
    if(!check)throw new Error('CONFIRMAÇÃO FINAL: recebimento não localizado.');
    if(check.photo_status!=='OK')throw new Error(`FOTOS: arquivos enviados, mas status ficou ${check.photo_status||'PENDING'} ${check.photo_error||''}`);
    opStatus(`SUCESSO ✓ Recebimento ${id} gravado em receipts e as duas fotos estão no Storage.`,'ok');
    toast('Recebimento gravado e fotos confirmadas.');
    f.reset();delete f.dataset.savedReceiptId;bindPhotoInputs();await refreshAndPatch();
  }catch(e){
    console.error(e);
    const saved=f.dataset.savedReceiptId;
    if(saved){
      opStatus(`DADOS GRAVADOS ✓ ID ${saved}. O banco está salvo. Falhou somente a etapa seguinte: ${errText(e)}`,'ok');
      toast('Dados gravados; veja o diagnóstico das fotos.');
    }else{
      opStatus(`NÃO GRAVOU NO BANCO: ${errText(e)}`);
      toast(`NÃO GRAVOU: ${errText(e)}`);
    }
  }finally{btn.disabled=false;btn.textContent=old}
}
async function saveProcessing(f){const d=fd(f),input=n(d.input_kg),output=n(d.output_kg),type=d.operation_type;if(input<=0||output<0||output>input)return toast('Revise os pesos: a saída não pode ser maior que a entrada.');const central=type==='CENTRAL_TRIM',inputStage=central?'WHOLE':'TRIMMED',outputStage=central?'TRIMMED':'CLEAN',fromLoc=central?'CENTRAL':'PRODUCTION',toLoc=fromLoc,inputCost=stageCost(d.protein_id,inputStage,d.event_date||today()),outputCost=output>0?input*inputCost/output:0,id=uid();assertOnline();const btn=f.querySelector('button[type="submit"]')||f.querySelector('button');btn.disabled=true;const old=btn.textContent;btn.textContent='Gravando etapa…';try{const specs=[['input_item','entrada-produto'],['input_scale','entrada-balanca'],['output_item','saida-produto'],['output_scale','saida-balanca']];for(const [field,label] of specs)if(!f.elements[field]?.files?.[0])throw new Error(`Tire/selecione a foto ${label}.`);const legacyWhole=input,legacyTrim=central?output:input,legacyClean=central?output:output,loss=Math.max(0,input-output),row={id,...base(d.event_date),protein_id:d.protein_id,lot:d.lot,location:fromLoc,whole_kg:legacyWhole,trimmed_kg:legacyTrim,clean_kg:legacyClean,loss_headtail_kg:central?loss:0,loss_cleaning_kg:central?0:loss,total_loss_kg:loss,yield_headtail_pct:central?(input?output/input:0):1,yield_total_pct:input?output/input:0,cost_kg:inputCost,loss_value:loss*inputCost,photos:[],photo_status:'PENDING',photo_error:null,notes:d.notes||null,operation_type:type,input_stage:inputStage,output_stage:outputStage,input_kg:input,output_kg:output,from_location:fromLoc,to_location:toLoc,stage_loss_kg:loss,stage_yield_pct:input?output/input:0,input_cost_kg:inputCost,output_cost_kg:outputCost};const {error}=await sb.from('processing_batches').insert(row);if(error)throw error;for(let i=0;i<specs.length;i++){const [field,label]=specs[i];await enqueuePhoto(f.elements[field].files[0],'processing_batches',id,label,null,i)}btn.textContent='Enviando fotos…';await flushPhotoQueue(id);toast(`${central?'Beneficiamento central':'Limpeza final'} salvo. Rendimento ${pct(row.stage_yield_pct)} · custo de saída ${brl(outputCost)}/kg.`);f.reset();bindPhotoInputs();await refreshAndPatch()}catch(e){console.error(e);toast(`NÃO SALVO: ${errText(e)}`)}finally{btn.disabled=false;btn.textContent=old}}
