async function saveLoss(f){const d=fd(f),cost=stageCost(d.protein_id,d.stage,d.event_date||today()),q=n(d.qty_kg);await saveCloud(f,'losses',{...base(d.event_date),protein_id:d.protein_id,location:d.location,stage:d.stage,qty_kg:q,cause:d.cause,cost_kg:cost,loss_value:q*cost,notes:d.notes||null},[{field:'photo_item',column:'photo_item_path',label:'produto'},{field:'photo_scale',column:'photo_scale_path',label:'balanca'}],'Perda salva')}
